const receiptRender=render,receiptDetail=detail,receiptMaterialDetail=materialDetail,receiptCommit=commitReceipt;
let inspections=[],referenceFiles={AAA:[],B:[],C:[]};
const gradeHelp={AAA:'Perfeito. Exportação, e-commerce e varejo. Manter líquido.',B:'Imperfeições de formato ou abertura. Eventos e revenda em freezers.',C:'Amostras e consumo da equipe. Destino: freezer da cozinha.'};
boxes.find(b=>b.id==='CX-006').sourcePackages=['PRETA-002'];
function pendingItems(){return [...boxes.filter(b=>b.analysis&&!b.blocked).map(b=>({...b,kind:'pop',name:b.flavor,unit:'un'})),...materialStock.filter(m=>m.analysis&&!m.blocked).map(m=>({...m,kind:'material'}))]}
function inspectionQueue(){return '<div class="notice">Confira o recebido, separe as unidades bloqueadas e libere somente o saldo aprovado.</div>'+ (pendingItems().length?pendingItems().map(i=>`<section class="panel row"><div><strong>${esc(i.name)}</strong><small>${esc(i.receiptId||'Exemplo inicial')} · ${esc(i.lot||'Sem lote')} · declarado: ${i.qty} ${esc(i.unit)}</small><div class="tags"><span class="tag warning">Em análise</span><span class="tag">${i.kind==='pop'?'Pops':'Material / insumo'}</span></div></div><button class="primary" onclick="inspectItem('${i.id}','${i.kind}')">Conferir</button></section>`).join(''):'<section class="panel"><h2>Tudo conferido</h2><p>Os próximos recebimentos aparecerão aqui.</p></section>')+'<section class="panel"><h2>Conferências concluídas</h2>'+(inspections.map((r,i)=>`<div class="row"><div><strong>${esc(r.name)}</strong><small>NF: ${r.expected} · contado: ${r.actual} · diferença: ${r.actual-r.expected} · bloqueado: ${r.rejected} ${esc(r.unit)}</small></div><button onclick="inspectionResult(${i})">Ver resultado</button></div>`).join('')||'<p>Nenhuma conferência concluída nesta sessão.</p>')+'</section>'}
function inspectItem(id,kind){const b=(kind==='pop'?boxes:materialStock).find(b=>b.id===id);if(!b?.analysis||b.blocked)return;go('Conferência');const pop=kind==='pop',step=pop||b.unit==='un'?'1':'0.001';$('app').innerHTML=`<div class="heading"><div><h1>Conferir ${esc(pop?b.flavor:b.name)}</h1><p>${esc(b.receiptId||'Exemplo inicial')} · ${esc(b.lot||'Sem lote')}</p></div><button onclick="go('Conferência')">Voltar</button></div><form id="inspect-form" class="receipt-form" onsubmit="submitInspection(event,'${id}','${kind}')"><section class="panel"><h2>1. Conferência física</h2><p>Quantidade declarada: <strong>${b.qty} ${pop?'pops':esc(b.unit)}</strong>. A contagem abaixo não altera a nota fiscal.</p><label>Quantidade realmente recebida<input name="actual" type="number" min="0" step="${step}" value="${b.qty}" required></label><label>Motivo da divergência ou rejeição<textarea name="reason" placeholder="Obrigatório se houver diferença ou unidades bloqueadas"></textarea></label></section><section class="panel"><h2>2. ${pop?'Classificar e encaixotar':'Liberar material'}</h2>${pop?`<div class="grade-grid">${['AAA','B','C'].map(g=>`<div class="grade-section"><span class="tag ${g}">${g}</span><p>${gradeHelp[g]}</p>${referenceFiles[g].map(f=>`<a href="${f.url}" target="_blank" rel="noopener">${esc(f.name)}</a>`).join(' · ')}${input(g,'Quantidade',g==='AAA'?b.qty:0,'number')}${select('dest'+g,'Destino',locations,g==='C'?4:2)}</div>`).join('')}</div><label class="checkline"><input name="clean" type="checkbox" required> Lavagem, limpeza e contagem concluídas</label><p>Uma caixa por sabor, classe e lote; até 100 pops por caixa. Restante em caixa parcial. Estado inicial: líquido, mesmo quando o destino é um freezer.</p>`:`<p>Sem classificação AAA/B/C e sem divisão em caixas de 100.</p>${select('destination','Destino aprovado',locations,2)}`}<label>Rejeitado / bloqueado<input name="rejected" type="number" min="0" step="${step}" value="0" required></label><p>Permanece em ${esc(locations[0])}, fora do saldo disponível. Não vira classe C automaticamente.</p></section>${pop?`<section class="panel"><h2>3. Etiquetas e rastreabilidade</h2>${input('fifo','Data de referência FIFO (padrão: recebimento)',b.date,'date')}<p>Não use a data de encaixotamento para reiniciar a idade do produto. O lote original será mantido.</p></section>`:''}<section class="panel"><h2>Caixas pretas de origem</h2><p>${(b.sourcePackages||[]).map(esc).join(', ')||'Nenhuma vinculada neste exemplo.'}</p>${b.sourcePackages?.length&&!pop?'<label class="checkline"><input type="checkbox" name="emptied"> Todas estas caixas estão vazias e prontas para retornar à fábrica</label><p>Marque somente após retirar todo o conteúdo, inclusive unidades bloqueadas.</p>':''}</section><p id="inspect-error" role="alert" class="receipt-error"></p><button class="primary" type="submit">Concluir conferência${pop?' e vincular caixas':''}</button></form>`}
function buildInspection(id,kind,d){const src=(kind==='pop'?boxes:materialStock).find(b=>b.id===id);if(!src||!src.analysis||src.blocked)throw Error('Este item já foi conferido ou não está disponível.');const pop=kind==='pop',whole=pop||src.unit==='un',num=v=>{if(v===''||v==null)throw Error('Preencha as quantidades.');const n=Number(v);if(!Number.isFinite(n)||n<0||(whole&&!Number.isInteger(n)))throw Error('Informe quantidades válidas.');return n},actual=num(d.actual),rejected=num(d.rejected),reason=(d.reason||'').trim(),counts=pop?['AAA','B','C'].map(g=>num(d[g])):[];if(pop&&Math.abs(counts.reduce((s,n)=>s+n,0)+rejected-actual)>0.00001)throw Error('AAA + B + C + bloqueados deve ser igual à quantidade contada.');if(rejected>actual)throw Error('Bloqueados não podem exceder o recebido.');if((actual!==src.qty||rejected)&&!reason)throw Error('Explique a diferença ou rejeição.');if(pop&&!d.clean)throw Error('Confirme a lavagem e a limpeza.');if(pop&&!/^\d{4}-\d{2}-\d{2}$/.test(d.fifo||''))throw Error('Informe a data FIFO.');const dests=pop?['AAA','B','C'].map(g=>Number(d['dest'+g])):[Number(d.destination)];if(dests.some(n=>!Number.isInteger(n)||n<0||n>=locations.length))throw Error('Selecione destinos válidos.');return {src,pop,actual,rejected,reason,counts,dests,fifo:pop?d.fifo:src.date,emptied:!!d.emptied}}
function commitInspection(id,kind,d){const p=buildInspection(id,kind,d),{src,pop,actual,rejected,reason,counts,dests}=p,generated=[];const record={sourceId:id,kind,name:pop?src.flavor:src.name,unit:pop?'un':src.unit,receiptId:src.receiptId,expected:src.qty,actual,rejected,reason,lot:src.lot,fifo:p.fifo,counts,generated,at:new Date().toISOString()};if(pop){boxes=boxes.filter(b=>b.id!==id);['AAA','B','C'].forEach((grade,i)=>{let remaining=counts[i];while(remaining>0){const qty=Math.min(100,remaining),box={...src,id:uniqueStockId('CX-'),qty,loc:dests[i],grade,state:'Líquido',active:false,analysis:false,date:p.fifo,receivedDate:src.date,packedAt:record.at,inspectionIndex:inspections.length};boxes.push(box);generated.push(box.id);remaining-=qty}});if(rejected)boxes.push({...src,id:uniqueStockId('BLQ-'),qty:rejected,analysis:false,blocked:true,grade:'Bloqueado',loc:0,active:false,inspectionIndex:inspections.length})}else{src.qty=Number((actual-rejected).toFixed(3));src.analysis=false;src.loc=dests[0];src.inspectionIndex=inspections.length;if(rejected)materialStock.push({...src,id:'BLQ-MAT-'+String(++seq),qty:rejected,loc:0,analysis:false,blocked:true});}
if(p.emptied)for(const code of src.sourcePackages||[]){const pkg=packages.find(b=>normalizeBoxCode(b.id)===normalizeBoxCode(code));if(pkg){pkg.status='Vazia · pronta para retorno';pkg.product='';}}record.emptyPackages=p.emptied?[...(src.sourcePackages||[])]:[];inspections.push(record);log(`Conferência ${id}: declarado ${record.expected}, contado ${actual}, bloqueado ${rejected}. ${reason} ${generated.length} caixas geradas.`);return inspections.length-1}
function submitInspection(e,id,kind){e.preventDefault();try{const n=commitInspection(id,kind,Object.fromEntries(new FormData(e.target)));inspectionResult(n);toast('Conferência registrada')}catch(err){$('inspect-error').textContent=err.message}}
function inspectionResult(n){const r=inspections[n];go('Conferência');$('app').innerHTML=`<div class="heading"><div><h1>Conferência concluída</h1><p>${esc(r.name)} · ${esc(r.lot||'Sem lote')}</p></div><button onclick="go('Inventário')">Ver inventário</button></div><section class="panel"><div class="stats">${[[r.expected,'Declarado'],[r.actual,'Contado'],[r.actual-r.expected,'Diferença'],[r.rejected,'Bloqueado']].map(([v,l])=>`<div class="stat"><span>${l}</span><strong>${v} <small>${esc(r.unit)}</small></strong></div>`).join('')}</div><p>${esc(r.reason||'Contagem sem divergências.')}</p></section>${r.generated.length?`<section class="panel"><h2>${r.generated.length} caixas geradas</h2>${r.generated.map(id=>{const b=boxes.find(x=>x.id===id);return `<div class="row"><div><strong>${id} · ${b.grade} · ${b.qty} pops</strong><small>${b.qty===100?'Completa':'Parcial'} · ${esc(locations[b.loc])} · ${esc(b.state)}</small></div><button onclick="detail('${id}')">Abrir</button></div>`}).join('')}<div class="actions"><button class="primary" onclick="showLabels(${n})">Etiquetas QR / imprimir</button></div></section>`:''}<section class="panel"><h2>Caixas de origem</h2><p>${r.emptyPackages.length?r.emptyPackages.map(esc).join(', ')+' · vazias e prontas para retorno':'Esvaziamento não confirmado. Confira em Embalagens.'}</p></section>`}
function showLabels(n){const r=inspections[n];go('Etiquetas');$('app').innerHTML=`<div class="heading no-print"><div><h1>Etiquetas das caixas</h1><p>QR identifica a caixa. Etiquetas de demonstração; dados desta sessão.</p></div><div class="actions"><button onclick="inspectionResult(${n})">Voltar</button><button class="primary" onclick="window.print()">Imprimir etiquetas</button></div></div><div class="label-grid">${r.generated.map(id=>{const b=boxes.find(x=>x.id===id),qr=qrcode(0,'M');qr.addData(b.id);qr.make();return `<article class="print-label"><div><strong>YOLO · ${esc(b.flavor)}</strong><h2>${b.id}</h2><p>${b.grade} · ${b.qty} pops · ${esc(b.state)}</p><p>Lote: ${esc(b.lot)}<br>FIFO: ${esc(b.date)}<br>Embalado: ${r.at.slice(0,10)}</p><small>DEMONSTRAÇÃO</small></div>${qr.createSvgTag(3,12)}</article>`}).join('')}</div>`}
detail=function(id){const b=boxes.find(x=>x.id===id);if(b?.blocked){toast('Estoque bloqueado: não disponível para retirada.');return}if(b?.analysis){inspectItem(id,'pop');return}receiptDetail(id);if(b?.inspectionIndex!=null)$('fields').insertAdjacentHTML('beforeend',`<div class="actions"><button type="button" onclick="$('modal').close();showLabels(${b.inspectionIndex})">Etiquetas deste lote</button></div>`)};
materialDetail=function(id){const m=materialStock.find(x=>x.id===id);if(m?.blocked){toast('Material bloqueado: não disponível para retirada.');return}if(m?.analysis){inspectItem(id,'material');return}receiptMaterialDetail(id)};
function packageStatus(p){return p.status||(p.product?'Com produto':p.location==='Fábrica'?'Na fábrica':'A conferir')}
packageMove=function(i){const p=packages[i];openForm('Caixa '+p.id,select('loc','Destino',['Fábrica',...locations],Math.max(0,['Fábrica',...locations].indexOf(p.location)))+select('status','Situação',['Com produto','Vazia · pronta para retorno','Na fábrica'],Math.max(0,['Com produto','Vazia · pronta para retorno','Na fábrica'].indexOf(packageStatus(p)))),d=>{if(d.loc==='0'&&d.status!=='1'&&d.status!=='2')throw Error('Confirme que a caixa está vazia antes de retornar.');p.location=['Fábrica',...locations][+d.loc];p.status=d.loc==='0'?'Na fábrica':['Com produto','Vazia · pronta para retorno','Na fábrica'][+d.status];log(`${p.id}: ${p.status} · ${p.location}`)})};
commitReceipt=function(d){const note=receiptCommit(d);for(const item of note.items)for(const c of item.codes){const p=packages.find(p=>normalizeBoxCode(p.id)===c);if(p)p.status='Com produto'}return note};
function refsHTML(){return `<section class="panel"><h2>Referências de classificação</h2><p>Adicione fotos e documentos da YOLO. Arquivos ficam disponíveis apenas nesta sessão.</p><div class="grade-grid">${['AAA','B','C'].map(g=>`<section class="grade-section"><h2>${g}</h2><p>${gradeHelp[g]}</p><label>Adicionar fotos ou documentos<input type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt" onchange="addReferences('${g}',this.files)"></label><div>${referenceFiles[g].map(f=>`<a href="${f.url}" target="_blank" rel="noopener">${f.image?`<img alt="${esc(f.name)}" src="${f.url}">`:''}${esc(f.name)}</a>`).join('')}</div></section>`).join('')}</div></section>`}
function addReferences(g,files){for(const f of files){if(f.size>5*1024*1024){toast('Limite de 5 MB por arquivo');continue}referenceFiles[g].push({name:f.name,url:URL.createObjectURL(f),image:f.type.startsWith('image/')})}render()}
render=function(){receiptRender();if(view==='Início')$('app').querySelector('.tiles').insertAdjacentHTML('beforeend','<button class="tile" onclick="go(\'Conferência\')"><span>✓</span>Conferência e caixas<small>Contar, classificar, encaixotar e etiquetar</small></button>');$('nav').insertAdjacentHTML('beforeend',`<button class="${view==='Conferência'?'active':''}" onclick="go('Conferência')">✓ &nbsp; Conferência</button>`);if(view==='Conferência'){$('app').insertAdjacentHTML('beforeend',inspectionQueue()+refsHTML())}if(view==='Notas fiscais')$('app').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Conferência dos recebimentos</h2>${inspectionQueue()}</section>`);if(view==='Cadastros')$('app').insertAdjacentHTML('beforeend',refsHTML());if(view==='Embalagens')$('app').querySelector('.panel').innerHTML='<h2>Caixas pretas · circuito da fábrica</h2>'+packages.map((p,i)=>`<div class="row"><div><strong>${esc(p.id)}</strong><small>${esc(p.location)} · ${esc(packageStatus(p))}</small></div><button onclick="packageMove(${i})">Movimentar</button></div>`).join('');if(view==='Inventário'){const approved=boxes.filter(b=>!b.analysis&&!b.blocked&&!b.awaitingPacking).reduce((s,b)=>s+b.qty,0),blocked=boxes.filter(b=>b.blocked).reduce((s,b)=>s+b.qty,0);$('app').querySelector('.stats').insertAdjacentHTML('afterend',`<div class="notice">Disponível fisicamente: ${approved} pops · Bloqueado: ${blocked} pops. Em análise e bloqueados não podem ser retirados.</div>`);}}
render();
